try {
  const res = pm.response.json();
  if (res.status === true && res.data) {
    pm.collectionVariables.set('userAccessToken', res.data.accessToken);
    pm.collectionVariables.set('userRefreshToken', res.data.refreshToken);
    console.log('user tokens saved. role =', res.data.role);
  } else {
    console.warn('Login/verify failed — tokens not stored. Check the response body.');
  }
} catch (e) { console.warn("Could not parse token response", e); }

